from typing import List


class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        if x == 1:
            return pow(y, n, mod)
        limit = min(n, x)
        stirling = [0] * (limit + 1)
        stirling[0] = 1
        for i in range(1, n + 1):
            for j in range(min(i, limit), 0, -1):
                stirling[j] = (stirling[j - 1] + j * stirling[j]) % mod
            stirling[0] = 0
        result = 0
        arrangements = 1
        power = 1
        for j in range(1, limit + 1):
            arrangements = arrangements * (x - j + 1) % mod
            power = power * y % mod
            result = (result + stirling[j] * arrangements % mod * power) % mod
        return result
